import gzip
from html import escape
from format_lecon import R,paras
def source(n):return gzip.open(R/f'ressources_ia/aips/fi_fr/{n}.txt.gz','rt').read()
def q(s):return '<blockquote><p>« '+escape(s.strip())+' »</p></blockquote>'
def extrait(s,t):assert t in s;return q(t)
def zone(s,a,b):
 i=s.index(a)+len(a);return q(s[i:s.index(b,i)])
def sec(l):
 s=source(48624)
 body=paras('Viscotears est un gel ophtalmique de carbomère, 2 mg/g, substitut lacrymal. La présentation en tube contient du cétrimide ; la présentation SDU est en dose unitaire sans ce conservateur.', 'Posologie adulte et association à d’autres topiques, citations AIPS :')+zone(s,'\nAdultes\n','\nEnfants et adolescents')+paras('Enfants et adolescents, citation AIPS :')+zone(s,'\nEnfants et adolescents\n','\nContre-indications')+paras('Ne pas inventer une dose pédiatrique à partir du schéma adulte.', 'Contre-indication, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('En cas de douleurs, modification de vision, irritation, rougeur persistante ou absence d’amélioration après quelques jours, interrompre le produit et réévaluer. Le gel ne remplace pas le bilan d’une kératite ou d’une autre affection grave.', 'Lentilles, citation AIPS :')+extrait(s,'Les lentilles de contact doivent être retirées avant l’application du gel, et il faut attendre environ 15 minutes avant de les remettre.'.replace('’',"'"))+paras('Utiliser le gel en dehors des heures de port. Ne pas toucher l’extrémité du récipient et ne pas conserver une unidose entamée ; pour le tube, respecter la durée après ouverture de la fiche.', 'Grossesse et allaitement, citation AIPS :')+zone(s,'\nGrossesse, allaitement\n','\nEffet sur')+paras('Une vision floue transitoire peut survenir : attendre sa disparition avant conduite ou machine. Le choix d’un autre lubrifiant nécessite sa propre notice ; les présentations ne sont pas supposées identiques.')
 return l.subwindow('viscotears','Viscotears : indication et posologie',body,(17,))
def bleph(l):
 s=source(44538)
 body=paras('Tobrex contient de la tobramycine : 3 mg/g pour la pommade ophtalmique et 3 mg/ml pour le collyre. L’indication couvre les infections du segment antérieur et des annexes dues à des bactéries sensibles, dont la blépharite.', 'Le choix d’un antibiotique nécessite une indication bactérienne ; il ne traite pas toute inflammation palpébrale. Cette fenêtre présente la pommade, sans lui attribuer la posologie du collyre.', 'Extrait exact AIPS de la dose adulte pour une infection légère à modérée :')+extrait(s,"En cas d'infections légères à modérées, appliquer 2 à 3 fois par jour env. 1,5 cm de pommade")+paras('La fiche précise une application dans le sac conjonctival de l’œil atteint. Le médecin fixe la durée et le contrôle ; le schéma HUG de pommade deux fois par jour dix jours est un protocole clinique distinct, pas une durée spécifique ajoutée à la citation AIPS.', 'Pédiatrie : la ligne posologique générale décrit l’absence d’ajustement dès deux mois. Les mises en garde distinguent toutefois strictement les formulations :')+zone(s,'\nUtilisation chez les enfants et les adolescents\n','\nRemarque pour les porteurs de lentilles')+paras('Ne pas convertir l’information pédiatrique de la pommade en autorisation du collyre chez le même enfant. Les restrictions du collyre liées au bore priment sur une lecture isolée de la ligne posologique générale.', 'Contre-indications, citation AIPS :')+zone(s,'\nContre-indications\n','\nMises en garde')+paras('Surveiller irritation et hypersensibilité, et tenir compte des allergies croisées aux aminoglycosides. Éviter un traitement prolongé non réévalué, qui peut favoriser des germes résistants ou une surinfection.', 'Prudence en cas de maladie neuromusculaire et de tobramycine systémique concomitante. Ne pas porter de lentilles pendant le traitement ; une infection cornéenne ou une baisse visuelle impose une filière spécialisée.', 'Grossesse et allaitement : la fiche réserve l’usage pendant la grossesse aux situations exceptionnelles avec indication impérative. Pendant l’allaitement, le risque pour le nourrisson ne peut être exclu ; décision individualisée entre interruption de l’allaitement et du médicament.', 'Une vision floue passagère nécessite d’attendre avant conduite ou machine. La pommade n’est jamais injectée dans l’œil et ne remplace pas le drainage ou le traitement systémique d’une infection profonde.')+paras('Extraits AIPS sur grossesse et allaitement :')+extrait(s,"Pendant la grossesse, Tobrex ne doit être utilisé qu'exceptionnellement et qu'en cas d'indication impérative.")+extrait(s,"On ne sait pas si la tobramycine est excrétée dans le lait maternel après application topique oculaire; un risque pour le nourrisson ne peut donc pas être exclu.")
 return l.subwindow('tobrex','Tobrex pommade : indication et limites',body,(1,16,18))
